BASE=Path(__file__).resolve().parents[1];OUT=BASE/'.cache/batch200/drafts/rewrite_spec'
R=[['拉丁复合词中的 -minēre','突出；伸出']]
P=R+[['拉丁 prōminēre → prōminēns','向前突出；显眼的'],['拉丁语直接借入或经旧法语 prominent → 英语 prominent','突出；显著；有名望']]
